const normalize = (str) => str.trim().toLowerCase();
const moment = require("moment")
const job_data = $input.getJob
const custom_field_label = $input.getConfig?.custom_field_name || ""
const custom_fields = job_data.custom_fields || []
const job_category_name = $input.getJob?.job_category?.category_name || ''
const job_categories = $input.getCategories || []
const customer = job_data.customer;
const service_tasks = $input.getServiceTasks
const service_task_name = $input.getConfig.service_task_name
const appointments = job_data.job_appointments
const find_date_custom_field = custom_fields.find(item => normalize(item.label) === normalize(custom_field_label))?.value || null
const find_service_task = service_tasks.filter(item => normalize(item.service_task_title) == normalize(service_task_name) )
let can_service_task_associate = true
if(find_service_task.length == 0){
  can_service_task_associate = false
}

const appointment_title = `${job_category_name} visit for ${customer.customer_first_name}`
const job_uid = job_data.job_uid;

const apoointment_payload = {
    "appointment": {
        "job_uid": job_uid,
        "appointment_title": appointment_title
    }
}

// Only schedule when we actually have a date/time
if (find_date_custom_field) {
    const find_category = job_categories.find(item => normalize(item?.category_name) == normalize(job_category_name));
    if (!find_category) {
        throw new Error("Category not Found")
    }
    const d = find_category?.estimated_duration;
    const total_minutes = (d?.days ?? 0) * 1440 + (d?.hours ?? 0) * 60 + (d?.minutes ?? 0);
    const start = moment(find_date_custom_field, 'YYYY-MM-DD HH:mm:ss');
    apoointment_payload.appointment.scheduled_start_time = start.format('YYYY-MM-DD HH:mm:ss');
    apoointment_payload.appointment.scheduled_end_time   = start.clone().add(total_minutes, 'minutes').format('YYYY-MM-DD HH:mm:ss');
}

const appointment_uid = appointments.appointments[0].appointment_uid
const appointment_association_url = `${$.getVariable('BASE_URL')}/appointments/${appointment_uid}/associations?job_uid=${job_uid}`
const association_payload = {
    "job_uid":job_uid ,
    "associations": find_service_task.map(item => ({
            "module": "SERVICE_TASK",
            "type": "ASSOCIATE",
            "module_uid": item.service_task_uid
        }))
}

const appointment_url = `${$.getVariable('BASE_URL')}/appointments`

return {
  data : {
      association_payload : {
        url : appointment_association_url,
        payload : association_payload,
        can_service_task_associate
      },
      appointment_update_payload :{
        url : appointment_url,
        payload : apoointment_payload
      }
  }
};
